        return el.closest(`[${inspectAttribute}]`);
      }
      return null;
    }

    document.addEventListener(
      'keydown',
      (event) => {
        window.__qwik_inspector_state.pressedKeys.add(event.code);
        updateOverlay();
      },
      { capture: true }
    );

    document.addEventListener(
      'keyup',
      (event) => {
        window.__qwik_inspector_state.pressedKeys.delete(event.code);
        updateOverlay();
      },
      { capture: true }
    );

    window.addEventListener(
